import{_ as t,c as o,o as s,ah as n}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"Release history","description":"","frontmatter":{"title":"Release history"},"headers":[],"relativePath":"releases/history.md","filePath":"releases/history.md"}'),r={name:"releases/history.md"};function a(i,e,l,g,d,h){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="release-history" tabindex="-1">Release history <a class="header-anchor" href="#release-history" aria-label="Permalink to &quot;Release history&quot;">​</a></h1><h2 id="_2-0-0-2026-01-23" tabindex="-1">[2.0.0] - 2026-01-23 <a class="header-anchor" href="#_2-0-0-2026-01-23" aria-label="Permalink to &quot;[2.0.0] - 2026-01-23&quot;">​</a></h2><h3 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h3><ul><li>Corporate-friendly build that does not require installation.</li><li>Version tracking and notifications for new updates.</li><li>Project moved to an <strong>iframe</strong> entry; <strong>popup</strong> is no longer the primary entry point.</li></ul><hr><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h3><ul><li>Fixed a memory spike on static sites, including Docusaurus and Hugo.</li></ul><hr><h3 id="ui-ux" tabindex="-1">UI / UX <a class="header-anchor" href="#ui-ux" aria-label="Permalink to &quot;UI / UX&quot;">​</a></h3><ul><li>Refreshed styles and overall visual design.</li></ul><h2 id="_2-1-0-2026-02-02" tabindex="-1">[2.1.0] - 2026-02-02 <a class="header-anchor" href="#_2-1-0-2026-02-02" aria-label="Permalink to &quot;[2.1.0] - 2026-02-02&quot;">​</a></h2><h3 id="core-1" tabindex="-1">Core <a class="header-anchor" href="#core-1" aria-label="Permalink to &quot;Core&quot;">​</a></h3><ul><li>New <strong>Network</strong> management tab.</li><li>Redesign for <strong>iframe</strong> layout instead of <strong>popup</strong> — more useful space on screen.</li><li>JSON layout tweaks — editor uses full app height.</li><li>Fixed tabs sticking when opening early — <strong>Props</strong> and <strong>Pinia</strong> no longer require a full page reload to appear.</li></ul><hr><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><ul><li>Fixed favorites not resolving after reload or repeated flows.</li><li>Optimized Props for long sessions without excessive CPU; internal refactor.</li><li>Props tab overhaul — better behavior with large trees and hover search.</li><li>Removed <strong>Props only</strong> mode.</li></ul><hr><h3 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h3><ul><li>Intercepts <strong>fetch</strong> and <strong>XMLHttpRequest</strong> except <strong>OPTIONS</strong> and extension-originated calls.</li><li>Summary columns: status, method, name, duration, size.</li><li>Detailed view: params, auth, headers, request, response — only CORS-exposed headers where applicable.</li><li>Pause/resume capture; recording on by default on first open.</li><li><strong>Breakpoint</strong> — pause and edit outbound requests before send.</li><li><strong>Mock Response</strong> — intercept and return a synthetic response.</li><li>Quick copy of URLs, tokens, and key fields.</li><li>Clear all captured requests.</li><li>Event-driven architecture without polling for lower CPU.</li><li>Binary detection — textual preview suppressed with metadata only.</li></ul><h2 id="_2-2-0-2026-02-24" tabindex="-1">[2.2.0] - 2026-02-24 <a class="header-anchor" href="#_2-2-0-2026-02-24" aria-label="Permalink to &quot;[2.2.0] - 2026-02-24&quot;">​</a></h2><h3 id="core-2" tabindex="-1">Core <a class="header-anchor" href="#core-2" aria-label="Permalink to &quot;Core&quot;">​</a></h3><ul><li><p><strong>Display Mode</strong> — move the app into a <strong>DevTools</strong> tab or disable pure overlay.</p></li><li><p><strong>Options</strong> reorganized into logical sections.</p></li><li><p><strong>Props</strong>, <strong>Pinia Store</strong>, and <strong>Network</strong> filters editable inline without jumping to Options.</p></li><li><p>Fixed JSON text-mode click target area.</p></li><li><p>Large JSON no longer truncates — heavy CSS disabled for performance.</p></li><li><p>Update notifications revised:</p><ul><li><strong>Dismiss</strong> → <strong>Later</strong>;</li><li><strong>Download</strong> → <strong>Preview</strong> pointing to <strong>Options → About</strong>;</li><li>detail block with <strong>Ignore</strong> and <strong>Download</strong>.</li></ul></li></ul><hr><h3 id="props-1" tabindex="-1">Props <a class="header-anchor" href="#props-1" aria-label="Permalink to &quot;Props&quot;">​</a></h3><ul><li>Fixed missing Props hover highlight in <strong>Standalone</strong>.</li></ul><hr><h3 id="network-1" tabindex="-1">Network <a class="header-anchor" href="#network-1" aria-label="Permalink to &quot;Network&quot;">​</a></h3><ul><li><strong>form-data</strong> support for reading and traffic substitution.</li><li>Saved files for reuse with <strong>Breakpoint</strong> / <strong>form-data</strong>.</li><li><strong>Rewrite Breakpoint</strong> / <strong>Rewrite Mock</strong> — overwrite existing rules instead of duplicating.</li><li>Badges for active <strong>Breakpoint</strong> / <strong>Mock</strong> per request; click opens matching Options.</li><li>Search by HTTP status code.</li><li><strong>Breakpoint</strong> rules consider HTTP method.</li><li>Fixed inspector not opening when a <strong>breakpoint</strong> fired.</li><li>Context menu entries: <strong>Disable/Enable Breakpoint</strong>, <strong>Disable/Enable Mock</strong>, <strong>Delete Breakpoint/Mock</strong> (shown when applicable).</li></ul><hr><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><h4 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h4><ul><li>Core settings (<strong>Display Mode</strong>, <strong>Search Parameters</strong>, <strong>Auto Refresh</strong>, <strong>JSON Editor Mode</strong>) grouped together.</li><li><strong>Settings Management</strong> moved from the tab header.</li></ul><h4 id="network-2" tabindex="-1">Network <a class="header-anchor" href="#network-2" aria-label="Permalink to &quot;Network&quot;">​</a></h4><ul><li><strong>Search Settings</strong> split into their own section and decoupled.</li><li><strong>Breakpoints</strong> / <strong>Mocks</strong> table layout fixes — rows no longer over-stretch.</li><li>Toggle and edit existing rules.</li></ul><h4 id="props-2" tabindex="-1">Props <a class="header-anchor" href="#props-2" aria-label="Permalink to &quot;Props&quot;">​</a></h4><ul><li>Settings file controls moved into the section.</li><li><strong>Component Blacklist</strong> moved here from the general block.</li><li><strong>Favorite Components</strong> moved here from the general block.</li></ul><h4 id="pinia-store" tabindex="-1">Pinia Store <a class="header-anchor" href="#pinia-store" aria-label="Permalink to &quot;Pinia Store&quot;">​</a></h4><ul><li>Settings file controls moved into the section.</li></ul><h4 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h4><ul><li><p><strong>Release notes</strong> and <strong>Check for updates</strong> (extension only).</p></li><li><p>When an update exists:</p><ul><li><strong>Ignore</strong> silences this version until a newer one ships;</li><li><strong>Download</strong> fetches the app archive.</li></ul></li></ul><h2 id="_2-3-0-2026-03-16" tabindex="-1">[2.3.0] - 2026-03-16 <a class="header-anchor" href="#_2-3-0-2026-03-16" aria-label="Permalink to &quot;[2.3.0] - 2026-03-16&quot;">​</a></h2><h3 id="network-3" tabindex="-1">Network <a class="header-anchor" href="#network-3" aria-label="Permalink to &quot;Network&quot;">​</a></h3><ul><li><strong>Postman</strong> collection export from captured <strong>Network</strong> traffic.</li><li>Single-panel mode: <strong>Copy cURL</strong> replaced with a header context menu — <strong>Breakpoint</strong>, <strong>Mock</strong>, <strong>Copy cURL</strong>.</li><li>Right-click context menu on request detail header.</li></ul><hr><h3 id="props-3" tabindex="-1">Props <a class="header-anchor" href="#props-3" aria-label="Permalink to &quot;Props&quot;">​</a></h3><ul><li>Favorites and blacklist behavior fixes.</li><li>Blacklist applied during collection traversal (not only table filtering) — faster Props load.</li><li>Quick actions menu for <strong>Props</strong>.</li><li>Refresh open component in read mode.</li><li>Shortcut jump to favorites from the favorites counter.</li></ul><hr><h3 id="store" tabindex="-1">Store <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Store&quot;">​</a></h3><ul><li>Pinia <strong>favorites</strong> with shortcut navigation.</li><li>Quick actions menu for <strong>Pinia Store</strong>.</li><li>Refresh open entry in read mode.</li><li><strong>Options</strong> supports manual favorite entries with <strong>wildcards</strong>.</li></ul><hr><h3 id="options-1" tabindex="-1">Options <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;Options&quot;">​</a></h3><ul><li>User files now persist as local copies in app storage.</li><li><strong>Standalone</strong> uses dedicated local storage — settings survive relaunch and work across sites.</li><li>Tree JSON editor temporarily disabled — text mode only.</li></ul><h4 id="customize" tabindex="-1">Customize <a class="header-anchor" href="#customize" aria-label="Permalink to &quot;Customize&quot;">​</a></h4><p><strong>Options → General → Customize</strong> adds theming:</p><ul><li><strong>Dark / Light</strong> color scheme;</li><li><strong>Image</strong> background (<strong>File / Link</strong>) with stills, <strong>GIF</strong>, <strong>MP4</strong>;</li><li><strong>Browse</strong> or pick from saved files;</li><li>Add by URL;</li><li><strong>Image Opacity</strong>, <strong>Blur</strong>, <strong>Noise Intensity / Opacity</strong>, <strong>Position (X / Y)</strong>, <strong>Scale</strong> (<strong>100–200%</strong>).</li></ul><hr><h3 id="ui-ux-1" tabindex="-1">UI / UX <a class="header-anchor" href="#ui-ux-1" aria-label="Permalink to &quot;UI / UX&quot;">​</a></h3><ul><li>Responsive layout for smaller screens.</li><li>Wide layout: split list + details.</li><li>~<strong>1000px</strong> width collapses to single-panel.</li><li><strong>Esc</strong> closes panels/dialogs.</li><li><strong>Ctrl+F</strong> search in <strong>DevTools</strong> tab mode.</li><li>Loading skeletons for <strong>Props</strong> / <strong>Pinia</strong> tables instead of raw “Not found”.</li><li>Column visibility toggles for <strong>Props</strong>, <strong>Pinia</strong>, <strong>Network</strong>.</li><li>Chevron redesign for iframe open/close.</li><li>Table context menus (right-click).</li></ul><hr><h3 id="performance-1" tabindex="-1">Performance <a class="header-anchor" href="#performance-1" aria-label="Permalink to &quot;Performance&quot;">​</a></h3><ul><li>Blacklist applied during Props tree pre-walk — faster data collection and tab load.</li></ul><hr><h3 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>JSON edit hit area while scrolling.</li><li><strong>Network</strong> tab freezes after long sessions.</li><li><strong>Ctrl+A</strong> selects only the focused input.</li><li>Reset/delete buttons respect <strong>disabled</strong> state.</li><li><strong>Options</strong> tables with many rows.</li><li>JSON edit mode styling.</li><li>Minor cosmetic fixes.</li></ul><h2 id="_2-4-0-2026-04-05" tabindex="-1">[2.4.0] - 2026-04-05 <a class="header-anchor" href="#_2-4-0-2026-04-05" aria-label="Permalink to &quot;[2.4.0] - 2026-04-05&quot;">​</a></h2><h3 id="network-4" tabindex="-1">Network <a class="header-anchor" href="#network-4" aria-label="Permalink to &quot;Network&quot;">​</a></h3><ul><li>When <strong>Pause</strong> is enabled, inspector interceptors are detached, so native DevTools display the <strong>original initiator</strong> instead of <strong>injected.ts</strong>.</li><li>The <strong>Network</strong> table now uses virtualization for better performance and reduced UI freezes.</li><li>The request details view now opens on the <strong>Response</strong> tab by default.</li><li>When a <strong>Breakpoint</strong> is triggered, the paused method automatically opens on the <strong>Request</strong> tab.</li><li><strong>Search by</strong> lists on the <strong>Network</strong> tab and in <strong>Options</strong> now support searching by the <strong>Name</strong> column.</li></ul><hr><h3 id="props-4" tabindex="-1">Props <a class="header-anchor" href="#props-4" aria-label="Permalink to &quot;Props&quot;">​</a></h3><ul><li><p><strong>Props</strong> performance has been significantly improved, making <strong>auto refresh</strong> safe to use.</p></li><li><p>In the <strong>Props</strong> table, the <strong>Props</strong> column has been split into <strong>Passed</strong> and <strong>Declared</strong> (all columns can be hidden):</p><ul><li><strong>Passed</strong> — number of props currently received;</li><li><strong>Declared</strong> — number of props declared on the component.</li></ul></li><li><p>In the right-side <strong>Props details</strong> panel, data is now split into two tabs:</p><ul><li><strong>Passed</strong> — props currently received (opened by default);</li><li><strong>Declared</strong> — all props declared by the component.</li></ul></li><li><p>The <strong>Props details</strong> panel now includes a <strong>Size</strong> parameter.</p></li></ul><h4 id="inspect-props-inspector" tabindex="-1">Inspect (Props Inspector) <a class="header-anchor" href="#inspect-props-inspector" aria-label="Permalink to &quot;Inspect (Props Inspector)&quot;">​</a></h4><ul><li>Added page element selection mode similar to <strong>Chrome DevTools Elements</strong>.</li><li>Allows selecting elements directly on the page for quick <strong>Props</strong> filtering.</li><li>Highlights <strong>Vue</strong> components on hover.</li><li>Displays quick element info: <strong>Name</strong>, <strong>Root element</strong>, <strong>Received Props</strong>, <strong>Nested components</strong>.</li><li>After selection, <strong>Props</strong> displays only the selected element and its nested components.</li><li>The filter can be quickly cleared via the <strong>Filtered</strong> badge.</li></ul><hr><h3 id="ui-ux-2" tabindex="-1">UI / UX <a class="header-anchor" href="#ui-ux-2" aria-label="Permalink to &quot;UI / UX&quot;">​</a></h3><h4 id="windowed-mode" tabindex="-1">Windowed mode <a class="header-anchor" href="#windowed-mode" aria-label="Permalink to &quot;Windowed mode&quot;">​</a></h4><ul><li>Added support for windowed mode with saved position for both launch modes.</li><li>Updated the iframe open chevron with a drag indicator.</li><li>Added support for docking the launcher to any of the four browser edges with automatic vertical stretching.</li></ul><h4 id="auto-launch-settings" tabindex="-1">Auto launch settings <a class="header-anchor" href="#auto-launch-settings" aria-label="Permalink to &quot;Auto launch settings&quot;">​</a></h4><ul><li><p>Added <strong>Whitelist</strong> for automatic app launch and <strong>Blacklist</strong> for excluded sites where launch and launcher display are disabled.</p></li><li><p>Added extension <strong>popup</strong> with quick actions:</p><ul><li><strong>Forced Launch</strong> — launches the app ignoring whitelist, blacklist, and static-site restrictions;</li><li><strong>Reset Settings</strong> — resets all extension settings.</li></ul></li></ul><h4 id="other-ui-improvements" tabindex="-1">Other UI improvements <a class="header-anchor" href="#other-ui-improvements" aria-label="Permalink to &quot;Other UI improvements&quot;">​</a></h4><ul><li>Fixed <strong>JSON</strong> styling for large data volumes.</li><li>Added exact search when entering values in quotes; without quotes, search works in <strong>like</strong> mode.</li><li>Minor visual interface improvements.</li><li>Improved <strong>Esc</strong> behavior in <strong>DevTools</strong> mode: first closes nested tabs, and when nothing else remains, opens the <strong>DevTools Console</strong>.</li></ul><hr><h3 id="performance-2" tabindex="-1">Performance <a class="header-anchor" href="#performance-2" aria-label="Permalink to &quot;Performance&quot;">​</a></h3><ul><li>Improved <strong>Props</strong> and <strong>Store</strong> detection mechanism for significantly faster data retrieval.</li><li>Increased limits for maximum readable <strong>Props</strong> count.</li><li>Refactored internal project structure: removed unused modules, dead code, and duplicated logic.</li></ul><hr><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Full project documentation has been added.</li><li>Added a <strong>Documentation</strong> section to the landing page.</li><li>Added quick documentation access via <strong>Options → About</strong>.</li></ul><hr><h3 id="fixes-1" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-1" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>Blocked native right-click menu inside the application context menu. • Fixed incorrect favorite detection in Props details when names matched.</li><li>Improved search behavior in <strong>DevTools mode</strong>: fixed cases where search could stop working and added highlight reset when clearing the field or closing search.</li><li>Fixed an issue when saving changes to <strong>Getters</strong> in <strong>Pinia Store</strong>.</li><li>Fixed an issue with retrieving <strong>Props</strong> data in <strong>Vue</strong> during local development.</li><li>Fixed <strong>Network</strong> issues during local development.</li></ul><h2 id="_2-5-0-2026-05-17" tabindex="-1">[2.5.0] - 2026-05-17 <a class="header-anchor" href="#_2-5-0-2026-05-17" aria-label="Permalink to &quot;[2.5.0] - 2026-05-17&quot;">​</a></h2><h3 id="network-5" tabindex="-1">Network <a class="header-anchor" href="#network-5" aria-label="Permalink to &quot;Network&quot;">​</a></h3><ul><li>Network header sections can be <strong>collapsed</strong> and <strong>expanded</strong>.</li><li>The app <strong>remembers the last details tab</strong> you used; when you open another request, it opens on the <strong>same tab</strong> you had selected while viewing the previous request.</li></ul><p><strong>Global suspend for Breakpoint and Mock</strong></p><p>On the <strong>Network</strong> toolbar (right side, next to log recording controls), two buttons were added: <strong>suspend / resume all breakpoint rules</strong> (pause-in-circle icon; active — <strong>amber</strong> accent) and <strong>suspend / resume all mock responses</strong> (shuffle icon; active — <strong>purple</strong> accent). Rules are <strong>not</strong> removed from <strong>Options → Network</strong>; when turned off, that interception type is <strong>not</strong> applied on the page. The same flags are controlled by <strong>Enable breakpoint rules</strong> and <strong>Enable mock responses</strong> next to the lists in <strong>Options</strong>; the toolbar and <strong>Options</strong> stay in sync. <strong>bp</strong> and <strong>mock</strong> badges use a <strong>muted</strong> style when global rule application is disabled.</p><p><strong>Network capture: Advanced mode</strong></p><p><strong>Network</strong> settings include <strong>Advanced mode</strong>: the extension requests additional permissions and collects the <strong>full</strong> request and response header set (including headers not always visible in the regular DevTools <strong>Network</strong> tab because of page limitations). <strong>Classic mode</strong> still shows only headers available in the standard “classic” view without bypassing those limitations.</p><p><strong>Standalone</strong></p><p>Advanced capture and related features are <strong>not available in Standalone</strong>: only the classic flow runs there, without extended headers and without Advanced-only menus and settings.</p><p><strong>What Advanced mode adds in Network</strong></p><ul><li><strong>Extra headers</strong> in the Request / Response areas on the selected request’s Headers tab.</li><li><strong>Pinned headers</strong> — pin names to the top of the list separately for <strong>request</strong> and <strong>response</strong>; edit pins in settings (Advanced only).</li><li><strong>Header links</strong> — per host and URL template, open an external resource with the header value substituted (e.g. traces, ID lookup, internal dashboards). Manage rules in <strong>Network</strong> settings and from the header row context menu (when Advanced).</li><li><strong>Header links</strong> and <strong>Pinned headers</strong> in <strong>Options</strong> are shown <strong>only when Advanced mode is enabled</strong> so Classic mode stays uncluttered.</li></ul><hr><h3 id="ui-ux-3" tabindex="-1">UI / UX <a class="header-anchor" href="#ui-ux-3" aria-label="Permalink to &quot;UI / UX&quot;">​</a></h3><p><strong>JSON Mode (<strong>Options → General</strong>)</strong></p><p><strong>Options → General</strong> now includes a <strong>JSON Mode</strong> switch with two options:</p><ul><li><strong>Classic</strong> — built-in text editor with Prism syntax highlighting (<strong>JsonTextEditor</strong>): a single text view with no tree, tuned for large payloads (reduced highlighting on very long JSON and a lightweight viewer for large non-JSON read-only bodies).</li><li><strong>Advanced</strong> — <strong>vanilla-jsoneditor</strong>: two views of the same JSON — <strong>Text</strong> (code) and <strong>Tree</strong> (structure); switch from the toolbar; the last selected mode (<strong>Text</strong> / <strong>Tree</strong>) is <strong>saved</strong> in settings (<strong>json.mode</strong>). Advanced provides <strong>Format</strong> / <strong>Compact</strong> (where editing is allowed), <strong>Undo / Redo</strong>, <strong>search</strong>, copy; in tree mode — expand/collapse, path navigation, context menus, and sort/edit flows built on the tree.</li></ul><p>The <strong>Classic / Advanced</strong> choice selects the JSON implementation across the UI (<strong>Network</strong> and <strong>Mock</strong> bodies, <strong>Pinia</strong> snapshots, JSON on <strong>Props</strong>, etc.). Non-JSON content still uses text view with highlighting where supported.</p><h2 id="_2-6-0-2026-10-17" tabindex="-1">[2.6.0] - 2026-10-17 <a class="header-anchor" href="#_2-6-0-2026-10-17" aria-label="Permalink to &quot;[2.6.0] - 2026-10-17&quot;">​</a></h2><h3 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h3><p>A new <strong>Logs</strong> tab: one chronological journal of page events. Available in the extension and in <strong>Bookmark</strong> (Standalone) mode, always placed after <strong>Pinia Store</strong>.</p><h4 id="event-types" tabindex="-1">Event types <a class="header-anchor" href="#event-types" aria-label="Permalink to &quot;Event types&quot;">​</a></h4><ul><li><strong>Send request</strong> / <strong>Receive response</strong> — <code>fetch</code> / <code>XMLHttpRequest</code> requests and responses with parameters, headers, body, status, duration and size.</li><li><strong>WebSocket open</strong> / <strong>WebSocket sent</strong> / <strong>WebSocket received</strong> / <strong>WebSocket closed</strong> — opening and closing connections, sent and received messages, headers, duration and the close reason.</li><li><strong>Change props</strong> — component prop changes with a <strong>Before</strong> / <strong>After</strong> comparison.</li><li><strong>Emit</strong> — component events, arguments, listener type and the parent chain.</li><li><strong>Change store</strong> — Pinia state changes with a <strong>Before</strong> / <strong>After</strong> comparison. An existing store keeps an initial snapshot; a new store keeps its full state at creation.</li><li><strong>Store action</strong> — arguments, result or error, status and duration of Pinia actions.</li><li><strong>Navigation</strong> — SPA navigation with <strong>From</strong> / <strong>To</strong>. The current page is saved when recording starts and after <strong>Clear</strong>.</li><li><strong>JS error</strong> — uncaught errors, unhandled promise rejections and page <code>console.error</code> calls. The message, source, location and stack are shown. Messages of Vue Inspector itself and of other browser extensions are not recorded.</li></ul><h4 id="table-and-details" tabindex="-1">Table and details <a class="header-anchor" href="#table-and-details" aria-label="Permalink to &quot;Table and details&quot;">​</a></h4><ul><li>Columns <strong>Time</strong>, <strong>Type</strong>, <strong>Event</strong>, with highlighting for errors and failed requests: <strong>4xx</strong> is a warning, <strong>5xx</strong> and errors are a critical status.</li><li>Filter by event type and search by names, keys and values. Search modes are set in <strong>Options → Logs → Search Settings</strong>; a quoted query matches exactly.</li><li><strong>Pause</strong> stops recording, <strong>Clear</strong> empties the journal. Events are collected from the moment the inspector starts, even if the <strong>Logs</strong> tab is opened later.</li><li>Details depend on the event type and include the relevant data: request parameters, headers, JSON, WebSocket messages, event arguments and state snapshots.</li><li>Prop and Pinia changes include a <strong>diff</strong> of added, removed and changed paths.</li><li>Actions menu: <strong>Export event</strong>, <strong>Copy cURL</strong>, jump to the paired request or response, <strong>Ignore</strong> to stop recording the selected group of events.</li></ul><h4 id="selection-and-export" tabindex="-1">Selection and export <a class="header-anchor" href="#selection-and-export" aria-label="Permalink to &quot;Selection and export&quot;">​</a></h4><ul><li>Select events with checkboxes, <strong>Shift + click</strong> for a range, <strong>Ctrl / Cmd + click</strong> to toggle individual rows.</li><li><strong>Export Logs (n)</strong> exports the selected events. With nothing selected, every event that matches the current filters is exported.</li><li>Requests and responses are always exported together.</li><li><strong>Export Logs</strong> and a single-event export create a self-contained HTML report, format version 1, that opens offline.</li><li>Pinia changes in the report keep the data needed to view <strong>Before</strong> / <strong>After</strong>, even when earlier events were not exported.</li></ul><h3 id="html-report" tabindex="-1">HTML report <a class="header-anchor" href="#html-report" aria-label="Permalink to &quot;HTML report&quot;">​</a></h3><p>A self-contained HTML report with a dark theme and no external resources.</p><ul><li>Sections <strong>Report</strong>, <strong>Network</strong>, <strong>WebSocket</strong>, <strong>Components</strong>, <strong>Pinia</strong>, <strong>Page</strong> with event counters.</li><li><strong>Overview</strong> summary, and <strong>Events</strong>, <strong>Errors</strong> and <strong>Failed requests</strong> cards that open the matching events.</li><li>Search by titles and inside data (<strong>in data</strong>).</li><li>Keyboard navigation (<strong>↑ / ↓</strong>, <strong>Esc</strong>) and direct links to events.</li><li>Details with the same tabs as <strong>Logs</strong>, and a jump between a request and its response.</li><li><strong>Locate</strong> opens the event list and brings the selected event into view.</li><li>A <strong>Support Vue Inspector</strong> section with links to Boosty and a USDT donation over Tron (TRC-20).</li></ul><h3 id="network-6" tabindex="-1">Network <a class="header-anchor" href="#network-6" aria-label="Permalink to &quot;Network&quot;">​</a></h3><ul><li>Select requests with checkboxes and export only the selected rows with <strong>Export Collection (n)</strong>.</li><li><strong>bp</strong> and <strong>mock</strong> counts open the list of active rules. <strong>Pause</strong> suspends a rule, <strong>×</strong> deletes it.</li><li>On a narrow panel, saving a <strong>Breakpoint</strong> / <strong>Mock</strong> or leaving the form with the back button closes the request details. On a wide panel they stay open.</li><li>After a request or response is edited at a <strong>Breakpoint</strong>, the data that was actually sent is shown.</li><li>WebSocket connections are listed as separate <strong>WS</strong> rows, including ones already open when the inspector starts.</li><li><strong>Headers</strong> shows the handshake headers, <strong>Messages</strong> shows sent and received frames, newest first. JSON is formatted; direction and size are shown.</li><li>The latest 200 messages of a connection are kept. WebSocket is not included in <strong>Export Collection</strong>; <strong>Breakpoint</strong> and <strong>Mock</strong> stay available for HTTP.</li><li><strong>Logs</strong> and the HTML report record WebSocket events separately: <strong>open</strong>, <strong>sent</strong>, <strong>received</strong>, <strong>closed</strong>.</li><li>A recognized Centrifuge close, for example <strong>3501</strong>, shows the reason and <strong>No automatic reconnect</strong>. Sending <code>{}</code> on that connection shows a warning that the socket may close.</li><li>Binary responses show a notice with the content type; in the HTML report it uses the same styling as the truncated-data warning.</li></ul><h3 id="props-pinia-store" tabindex="-1">Props / Pinia Store <a class="header-anchor" href="#props-pinia-store" aria-label="Permalink to &quot;Props / Pinia Store&quot;">​</a></h3><p>Saving removed keys in <strong>Edit</strong> mode is fixed.</p><ul><li><strong>Pinia</strong> — nested keys are deleted from the store; removing top-level keys is handled for both options stores and setup stores.</li><li><strong>Props</strong> — a removed prop gets the value Vue uses for a prop that is not passed: its <strong>default</strong>, <code>false</code> for <strong>Boolean</strong>, otherwise <code>undefined</code>. Nested keys of object props are deleted.</li></ul><h3 id="options-→-logs" tabindex="-1">Options → Logs <a class="header-anchor" href="#options-→-logs" aria-label="Permalink to &quot;Options → Logs&quot;">​</a></h3><ul><li><strong>Search Settings</strong> — default search modes.</li><li><strong>Ignore list</strong> — ignored event groups, with <strong>Log again</strong> and <strong>Log all again</strong>.</li><li><strong>Logs and limits</strong> — turn event types on and off, memory budget, event size limit and the <strong>Used X of Y</strong> indicator.</li><li><strong>Data masking</strong> — masking of sensitive data, patterns and the key list.</li></ul><h4 id="data-storage-and-limits" tabindex="-1">Data storage and limits <a class="header-anchor" href="#data-storage-and-limits" aria-label="Permalink to &quot;Data storage and limits&quot;">​</a></h4><ul><li>Sensitive data is masked when an event is recorded, by keys and by value patterns, including JWT, <strong>Bearer</strong> / <strong>Basic</strong> and card numbers.</li><li>The default memory budget is <strong>20 MB</strong>. When the limit is reached, older events are dropped.</li><li>Pinia change history is compacted into a <strong>Store checkpoint</strong>, so the remaining changes can still be viewed.</li><li>Repeated values are stored once and restored in full in the UI and in the HTML report.</li><li>Events are stored whole by default. An optional event size limit of <strong>512 KB</strong> limits the volume by dropping large parts of events and truncating network bodies.</li></ul><h3 id="ui-ux-4" tabindex="-1">UI / UX <a class="header-anchor" href="#ui-ux-4" aria-label="Permalink to &quot;UI / UX&quot;">​</a></h3><ul><li><strong>Options</strong> has a <strong>Support Vue Inspector</strong> section with links to Boosty and a USDT donation over Tron (TRC-20).</li><li>Filter dropdowns use the UI kit scrollbar instead of the browser scrollbar.</li><li>The favorites column in <strong>Pinia</strong> is aligned with the columns in <strong>Props</strong>, <strong>Network</strong> and <strong>Logs</strong>.</li></ul><h3 id="fixes-2" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-2" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>Fixed the inspector failing to start when page global names clashed with names in the injected scripts.</li><li>Fixed <strong>Breakpoint</strong> with relative request and response URLs.</li><li>Fixed the display of the request and response data that was actually sent after a <strong>Breakpoint</strong> edit.</li><li>Fixed applying edited <code>XMLHttpRequest</code> headers when the URL and method did not change.</li><li>Fixed resolving relative URLs that were edited at a <strong>Breakpoint</strong>.</li><li>Fixed saving removed keys when editing <strong>Pinia</strong> and <strong>Props</strong>.</li></ul><h2 id="_2-7-0-2026-11-18" tabindex="-1">[2.7.0] - 2026-11-18 <a class="header-anchor" href="#_2-7-0-2026-11-18" aria-label="Permalink to &quot;[2.7.0] - 2026-11-18&quot;">​</a></h2><h3 id="ai-assistant" tabindex="-1">AI assistant <a class="header-anchor" href="#ai-assistant" aria-label="Permalink to &quot;AI assistant&quot;">​</a></h3><p>A new <strong>AI</strong> tab, after <strong>Logs</strong>. Describe the problem: the assistant explains what went wrong, the likely cause, the evidence and how to fix it. The same chat works in the extension and in <strong>Bookmark</strong> mode.</p><p><strong>What you can ask</strong></p><ul><li>Why a request failed, where an error comes from, or what changed after a navigation. The assistant starts from the captured logs and reads the page code when the logs are not enough. With source maps, the answer points at the original Vue file.</li><li>Why a button is disabled, an element is hidden or a message appears — also when the logs recorded nothing. It checks the live page: the component, the current props and store state, and the conditions in the code.</li><li>Where a value sits in the logged data: find it, list the matching rows or count them (for example filters that are visible by default, or rows with no price).</li><li>How to reproduce the session: the clicks, in order, as a scenario.</li><li>How Vue Inspector itself works: where a setting is and what a feature does.</li></ul><p><strong>Ask AI</strong> on a row in <strong>Network</strong>, <strong>Props</strong>, <strong>Pinia</strong> or <strong>Logs</strong> attaches that item to the question. Several items can be attached. An event id in the answer opens that event on <strong>Logs</strong>.</p><p><strong>Files</strong></p><p><strong>+</strong> next to the field attaches a <strong>Text file</strong> (TXT, LOG, JSON, HAR, MD, CSV, PDF) or a <strong>Vue inspector Log</strong>. Files can also be dropped on the field or pasted into it, up to 64 MB each. A long paste, over 4000 characters or 60 lines, becomes a <strong>Pasted text</strong> chip and is handled like a file.</p><p>A text file goes with the question it was attached to. The assistant can read it again in later questions of the same chat, and <strong>New chat</strong> drops it. An exported log stays pinned to the chat: the logs digest and the logs tools read it instead of the live capture until <strong>New chat</strong>.</p><p>A small file goes to the assistant whole. A bigger file is not sent: the assistant gets an overview and tools to search the file, read parts of it and query JSON or HAR by path. The first step of the answer says <strong>(overview; content read with file tools)</strong>. For a PDF only the text layer is read; scanned pages and password-protected files are refused.</p><p>The answer appears as it is written. Stopping keeps the text written so far; reasoning stays on one line until you expand it. Under the answer: which model answered, how many requests it took, tokens and time. A follow-up sends only the events captured since the last answer.</p><p><strong>Connection and models</strong></p><p><strong>Options → AI → Connection</strong> takes a free API key of <strong>Gemini</strong> (Google AI Studio) or <strong>OpenRouter</strong>. <strong>Your own providers</strong> adds OpenAI, DeepSeek, Ollama, LM Studio or any OpenAI-compatible server or agent, with an optional API key. The key stays in this browser: it is not part of settings export, and <strong>Reset</strong> does not remove it.</p><p>The model list starts with <strong>Auto</strong>. Auto picks an available model and moves to the next when one runs out of quota, cannot be used with the key, or is overloaded, and it remembers that until the quota resets, the key changes, or the model is free again. A model you pick yourself is always the one used. When it fails, the answer says why and offers <strong>Switch to Auto and try again</strong>. The line under the message field shows today&#39;s requests and how many models Auto is skipping.</p><p><strong>Options → AI → Models</strong> lists the recommended models and the ones you add, free and paid. Uncheck a model to hide it from the tab and from <strong>Auto</strong>. Each row shows today&#39;s requests and, when it applies, that the quota is used up, the key cannot use it, or it is busy. Models whose providers are down are hidden; models that fail often are marked <strong>unstable</strong>.</p><p><strong>How answers are written</strong></p><p><strong>Options → AI → Personalization</strong>:</p><ul><li><strong>Base style and tone</strong> — <strong>Default</strong>, <strong>Professional</strong>, <strong>Friendly</strong>, <strong>Direct</strong> or <strong>Mentor</strong>.</li><li><strong>Answer detail</strong> — <strong>Brief</strong> (cause, evidence and the fix), <strong>Normal</strong>, or <strong>Detailed</strong> (the chain of events, ruled-out causes, steps to reproduce).</li><li><strong>Instruction routing</strong> — <strong>Full</strong> sends every task instruction with each request, for strong models. <strong>Lite</strong> sends the core rules and loads the instructions of the current task.</li><li><strong>Your style instructions</strong> — your own text, up to 2000 characters. For example: answer in Russian, end with a checklist for the bug report.</li></ul><p><strong>What may be sent</strong></p><p>Before the first question the tab shows what goes to the provider. <strong>I understand</strong> confirms it. <strong>Review access</strong> opens <strong>Agent access</strong>.</p><p><strong>Options → AI → Agent access</strong> sets what the assistant may read and send:</p><ul><li><strong>Attach the logs digest</strong> — a short summary of errors and the timeline. On by default; off, the question goes out without it.</li><li><strong>Logs</strong>, <strong>Page code</strong> and <strong>Live page</strong> — each is <strong>Allowed</strong>, <strong>Ask each time</strong> or <strong>Off</strong>. <strong>Off</strong> means that group is not offered. <strong>Ask each time</strong> (the default) shows the call and waits for <strong>Allow</strong>, <strong>Allow in this chat</strong> or <strong>Deny</strong>.</li><li><strong>Request and response headers</strong>, <strong>bodies and WebSocket messages</strong>, and <strong>values of store state, props, emits and actions</strong> — each <strong>Allowed</strong> or <strong>Off</strong>. Off, names and types stay, values do not. Headers are the ones the page itself can see.</li></ul><p>The first step of an answer says what was sent, which access is in force and how many values were masked.</p><p><strong>Options → AI → Data masking for AI</strong> is a separate list from <strong>Logs</strong>. Passwords, tokens, API keys, cookies, sessions and token-like values (JWT, Bearer, card numbers) are sent as <code>[MASKED]</code>, including values found in page code. The <strong>Logs</strong> view and its exports stay as they are.</p><hr><h3 id="props-5" tabindex="-1">Props <a class="header-anchor" href="#props-5" aria-label="Permalink to &quot;Props&quot;">​</a></h3><p><strong>Save as</strong>, under the buttons of a component card, chooses what <strong>Save</strong> keeps. <strong>Once</strong> changes the live component only and removes a rule it already has. <strong>Part</strong> stores just the props changed in this edit. <strong>Full</strong> stores every current prop. A component has one of these. After a reload, or when the component is created again, a Part or Full rule is applied before <code>setup()</code> and the first render. The rule matches this component name at the same route of parent components, on the site where it was saved. Values are JSON, so functions cannot be kept.</p><p>While a rule applies, updates from the parent do not overwrite it. Turning the rule off or deleting it gives the component the parent&#39;s current value back at once, without a reload.</p><p>A row with a rule has a purple bar on the left, and the selected row has a purple background, like a mocked request on <strong>Network</strong>. The Props toolbar shows a pin with how many rules apply on this page out of the total; the card shows a pin with the number of props the rule holds. Both open <strong>Options → Props → Prop rules</strong>. <strong>Save as</strong> shows <strong>Part</strong> or <strong>Full</strong> when a rule applies, and <strong>Once</strong> otherwise. It can be changed only while editing; <strong>Cancel</strong> restores it. <strong>Delete rule</strong> in the row menu deletes the rule at once.</p><p><strong>Options → Props → Prop rules</strong>, after <strong>Favorite Components</strong>, lists the rules. <strong>Apply rules</strong> turns them all off without deleting them. The row menu has <strong>Edit</strong>, <strong>Enable</strong> / <strong>Disable</strong> and <strong>Delete</strong>.</p><p>In the extension the rules apply on page load even when the panel is closed. A page that loads Vue 3.3 or newer through a bundler gets the values on the first render. Other builds and Vue 2 get them once the inspector starts.</p><hr><h3 id="logs-1" tabindex="-1">Logs <a class="header-anchor" href="#logs-1" aria-label="Permalink to &quot;Logs&quot;">​</a></h3><p><strong>Export for AI</strong>, next to <strong>Export Logs</strong>, downloads a short Markdown digest of the selected events, or of every event that matches the filters. It is meant to be handed to an assistant and is many times smaller than the full report: how to read the file, a <strong>Summary</strong>, grouped <strong>Problems</strong> and a <strong>Timeline</strong>. An event id <code>#N</code> opens the same event in the HTML report.</p><p><strong>Click</strong> records a primary click: the control and the text on it. A click on an icon inside a button is recorded as the button. Clicks on Vue Inspector itself are skipped, and the value of a password or hidden field is not stored. <strong>Clicks</strong> is its own switch in <strong>Options → Logs</strong>, on by default.</p><p>A request and its response are exported together. The <strong>ignored</strong> badge opens <strong>Options → Logs</strong> at the ignore list.</p><h3 id="network-7" tabindex="-1">Network <a class="header-anchor" href="#network-7" aria-label="Permalink to &quot;Network&quot;">​</a></h3><ul><li>A WebSocket row can be sent to the assistant with <strong>Ask AI</strong>.</li><li>The <strong>bp</strong> and <strong>mock</strong> badges open <strong>Options → Network</strong> at the breakpoints or mocks. A pulsing pending breakpoint still selects the first pending row.</li><li>WebSocket <strong>Messages</strong> read as a chat: the composer at the bottom, sent frames on the right, received on the left, newest at the bottom.</li></ul><h3 id="html-report-1" tabindex="-1">HTML report <a class="header-anchor" href="#html-report-1" aria-label="Permalink to &quot;HTML report&quot;">​</a></h3><ul><li><strong>Export for AI</strong> downloads the same digest. <strong>Export JSON</strong> saves the full report data, including from a compressed report. On a narrow screen the buttons are <strong>Export AI</strong> and <strong>JSON</strong>.</li><li><strong>Failed requests / WS</strong> also counts WebSocket connections that closed with an error, closed without reconnecting, or failed.</li><li><strong>Page</strong> lists <strong>Click</strong> next to <strong>Navigation</strong> and <strong>JS error</strong>.</li></ul><h3 id="options-→-logs-1" tabindex="-1">Options → Logs <a class="header-anchor" href="#options-→-logs-1" aria-label="Permalink to &quot;Options → Logs&quot;">​</a></h3><ul><li><strong>Compress report</strong>, on by default, stores the report as gzip. The file is several times smaller and opens the same way. It needs Chrome / Edge 80+, Firefox 113+ or Safari 16.4+. In a browser without gzip the option is off and the report stays uncompressed.</li><li><strong>Requests</strong> and <strong>WebSocket</strong> are separate switches. WebSocket can be turned off while HTTP requests stay on.</li><li>The <strong>Ignore list</strong> is shown again, above <strong>Data masking</strong>.</li></ul><h3 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h3><p><strong>Options → General → Language</strong> switches the inspector interface. The choice is saved with the settings and starts as English. Available languages: English, Spanish, Simplified Chinese, German, French, Japanese, Portuguese (Brazil), Russian, Korean, Italian, Polish, Turkish, and Arabic.</p><h3 id="fixes-3" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-3" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>Fixed the false <strong>Body truncated</strong> notice on complete responses with non-ASCII text, such as Cyrillic. Reports exported before this fix no longer show that notice either.</li><li>Removed <strong>Search by Label</strong> in <strong>Props</strong>. The checkbox did not filter the list.</li><li>The <strong>Support Vue Inspector</strong> title lines up with the text of the card.</li><li>Minor layout fixes.</li></ul>',177)])])}const u=t(r,[["render",a]]);export{p as __pageData,u as default};
